#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Render the Anon Aadhaar real-proof fixture as Solidity constants.

Reads fixture.json from this directory and writes AadhaarRealProofFixture.sol next to it. Tests may
read files only under test/fixtures/kats and out, so the fork tests take the fixture from these constants
instead of reading the file. Run it from anywhere:

    python3 test/fixtures/aadhaar/generate.py

The output is deterministic, so running it again on an unchanged fixture.json leaves the .sol file
unchanged, which `git diff --exit-code` confirms.
"""

import json
import pathlib

HERE = pathlib.Path(__file__).resolve().parent
FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617


def underscored(value):
    """A decimal literal grouped in thousands, the way forge fmt writes it."""
    text = str(value)
    if len(text) < 5:
        return text
    groups = []
    while text:
        groups.insert(0, text[-3:])
        text = text[:-3]
    return '_'.join(groups)


def uint_constant(lines, doc, name, value):
    assert 0 <= value < 2**256, name
    declaration = f'  uint256 internal constant {name} = {underscored(value)};'
    lines.append(f'  /// @notice {doc}')
    if len(declaration) <= 120:
        lines.append(declaration)
    else:
        lines.append(f'  uint256 internal constant {name} =')
        lines.append(f'    {underscored(value)};')
    lines.append('')


def main():
    data = json.loads((HERE / 'fixture.json').read_text())
    digest = data['digest']
    assert digest.startswith('0x') and len(digest) == 66, digest
    bytes.fromhex(digest[2:])
    seed = int(data['nullifierSeed'])
    key = int(data['testPublicKeyHash'])
    packed = [int(x) for x in data['packed']]
    inputs = [int(x) for x in data['publicSignals']]
    raw_a = [int(x) for x in data['proof']['pi_a']]
    raw_b = [[int(x) for x in pair] for pair in data['proof']['pi_b']]
    raw_c = [int(x) for x in data['proof']['pi_c']]

    # The packed proof is the raw proof with each coordinate pair of b swapped, and the inputs carry the key and
    # seed the file names. A mismatch means fixture.json was edited by hand.
    assert len(packed) == 8 and len(inputs) == 9
    assert packed[0:2] == raw_a[0:2] and packed[6:8] == raw_c[0:2]
    assert packed[2:6] == [raw_b[0][1], raw_b[0][0], raw_b[1][1], raw_b[1][0]]
    assert inputs[0] == key and inputs[7] == seed
    assert all(x < FIELD for x in packed + inputs)

    lines = [
        '// SPDX-License-Identifier: GPL-3.0-or-later',
        'pragma solidity 0.8.30;',
        '',
        '// Generated by test/fixtures/aadhaar/generate.py from fixture.json. Do not edit by hand.',
        '//',
        '// The proof was made once with gen.js, @anon-aadhaar/core 2.4.3, snarkjs 0.7.6 and the v2.0.0 proving',
        '// artifacts, over the test QR data of anon-aadhaar/anon-aadhaar at commit',
        '// 4dad918761cfb1d7d5ed9918dcd796d0cb23ae82 (MIT, Copyright (c) 2022 Ethereum Foundation). See README.md',
        '// and NOTICE in this directory. Proving is randomized, so the values are frozen and never regenerated.',
        '',
        '/// @notice One real Anon Aadhaar proof, as constants. It proves a sample identity that upstream re-signed with',
        '///         its published test key, so it verifies only under the test public-key hash, which never enters a',
        '///         deployment. It binds the digest below as its signal and uses the nullifier seed below.',
        'abstract contract AadhaarRealProofFixture {',
        '  /// @notice The digest the proof binds as its signal.',
        f'  bytes32 internal constant _AADHAAR_REAL_DIGEST = {digest.lower()};',
        '',
    ]
    uint_constant(lines, 'The nullifier seed the proof was made with.', '_AADHAAR_REAL_NULLIFIER_SEED', seed)
    uint_constant(lines, "Upstream's test public-key hash, the key that signed the test QR data.",
                  '_AADHAAR_REAL_TEST_KEY_HASH', key)
    for index in range(2):
        uint_constant(lines, f'Coordinate {index} of point a.', f'_AADHAAR_REAL_A_{index}', packed[index])
    for row in range(2):
        for col in range(2):
            uint_constant(lines, f'Point b, pair {row}, word {col}, in the order the verifier expects.',
                          f'_AADHAAR_REAL_B_{row}_{col}', packed[2 + 2 * row + col])
    for row in range(2):
        for col in range(2):
            uint_constant(lines, f"Point b, pair {row}, word {col}, in snarkjs's order, before the swap.",
                          f'_AADHAAR_REAL_RAW_B_{row}_{col}', raw_b[row][col])
    for index in range(2):
        uint_constant(lines, f'Coordinate {index} of point c.', f'_AADHAAR_REAL_C_{index}', packed[6 + index])
    for index, value in enumerate(inputs):
        uint_constant(lines, f'Public input {index} of 9.', f'_AADHAAR_REAL_INPUT_{index}', value)
    lines += [
        '  /// @notice The proof as the verifier takes it.',
        '  /// @return _a Point a.',
        '  /// @return _b Point b, each pair in the order the verifier expects.',
        '  /// @return _c Point c.',
        '  /// @return _inputs The nine public inputs.',
        '  function _aadhaarRealProof()',
        '    internal',
        '    pure',
        '    returns (uint256[2] memory _a, uint256[2][2] memory _b, uint256[2] memory _c, uint256[9] memory _inputs)',
        '  {',
        '    _a = [_AADHAAR_REAL_A_0, _AADHAAR_REAL_A_1];',
        '    _b = [[_AADHAAR_REAL_B_0_0, _AADHAAR_REAL_B_0_1], [_AADHAAR_REAL_B_1_0, _AADHAAR_REAL_B_1_1]];',
        '    _c = [_AADHAAR_REAL_C_0, _AADHAAR_REAL_C_1];',
    ]
    for index in range(len(inputs)):
        lines.append(f'    _inputs[{index}] = _AADHAAR_REAL_INPUT_{index};')
    lines += [
        '  }',
        '',
        "  /// @notice Point b in snarkjs's order, each pair not yet swapped.",
        '  /// @return _b Point b as snarkjs writes it.',
        '  function _aadhaarRealRawB() internal pure returns (uint256[2][2] memory _b) {',
        '    _b = [[_AADHAAR_REAL_RAW_B_0_0, _AADHAAR_REAL_RAW_B_0_1], [_AADHAAR_REAL_RAW_B_1_0, _AADHAAR_REAL_RAW_B_1_1]];',
        '  }',
        '}',
        '',
    ]
    (HERE / 'AadhaarRealProofFixture.sol').write_text('\n'.join(lines))


if __name__ == '__main__':
    main()
